INSERT INTO `declaration_items` (`slug`, `locale`, `translation_group`, `title`, `summary`, `body`, `body_content_mode`, `body_blocks`, `kind`, `list_section`, `meta_line`, `band_label`, `badge_label`, `cta_label`, `cta_href`, `sort_order`, `publication_state`, `published_at`, `created_at`, `updated_at`, `deleted_at`) VALUES ('plaidoyer-jeunesse-decisions','fr','decl-youth-decisions','Pour une jeunesse au cœur des décisions publiques','GoV Gen Z Madagascar appelle à l\'intégration systématique de la jeunesse malgache dans les processus de décision institutionnelle — budgets participatifs, conseils consultatifs, commissions législatives. Les 55 % de jeunes ne peuvent rester spectateurs de leur propre avenir.',NULL,'blocks','[{\"type\":\"section_rich\",\"heading\":\"Pourquoi inclure la jeunesse\",\"heading_style\":\"warm\",\"intro\":\"Plus de la moitié de la population malgache a moins de 25 ans. Pourtant, les jeunes restent sous-représentés dans les débats budgétaires, les commissions législatives et les instances de planification qui dessinent leur avenir.\",\"bullets\":[\"55 % de Malagasy sont jeunes — projections démographiques INSTAT\",\"Peu de budgets participatifs incluent des délégués de moins de 30 ans\",\"Les conseils consultatifs publient rarement comptes rendus et retours citoyens\"],\"extra_paragraphs\":[]},{\"type\":\"section_rich\",\"heading\":\"Ce que nous demandons aux institutions\",\"heading_style\":\"teal\",\"intro\":\"GoV Gen Z Madagascar appelle à des mécanismes d’inclusion concrets et mesurables — pas des forums jeunesse symboliques.\",\"bullets\":[\"Réserver des sièges jeunesse aux commissions législatives sur l’éducation, l’emploi et le numérique\",\"Lancer des budgets participatifs pilotes dans au moins 5 régions avec résultats publiés\",\"Publier ordres du jour, comptes rendus et suites des conseils consultatifs sous 30 jours\",\"Suivre des indicateurs d’inclusion jeunesse dans les rapports annuels de gouvernance\"],\"extra_paragraphs\":[]},{\"type\":\"note_panel\",\"section_title\":\"Rejoindre le plaidoyer\",\"heading_style\":\"teal\",\"message\":\"Institutions, médias et citoyens : contactez-nous pour co-signer ce plaidoyer ou proposer un mécanisme d’inclusion concret dans votre secteur.\",\"submessage\":\"contact@govgenz.org · Objet : Plaidoyer inclusion jeunesse\"},{\"type\":\"sources\",\"section_title\":\"Sources et références\",\"lines\":[\"INSTAT — Perspectives démographiques Madagascar (projections 2024–2026)\",\"PNUD — Jeunesse, gouvernance et participation citoyenne en Afrique (2023)\",\"GoV Gen Z Madagascar — cartographie interne secteurs, programme Gouvernance (2026)\"]}]','pledge','declarations','Mai 2026 · Gouvernance','','Plaidoyer','Nous soutenir','mailto:contact@govgenz.org',10,'published','2026-05-01 10:00:00','2026-06-01 21:35:10','2026-06-04 08:02:40',NULL),('declaration-principes-2026','fr','decl-principles-2026','Déclaration de principes — GoV Gen Z Madagascar','GoV Gen Z Madagascar déclare son engagement total pour une gouvernance éthique, transparente et orientée vers le peuple malgache. Aucune décision ne sera prise sans documentation publique, aucune position ne sera défendue sans sources vérifiables.',NULL,'blocks','[{\"type\":\"section_rich\",\"heading\":\"Nos engagements publics\",\"heading_style\":\"teal\",\"intro\":\"Cette déclaration de principes fixe la base éthique de chaque position, projet et partenariat annoncé par GoV Gen Z Madagascar.\",\"bullets\":[\"Documenter toute décision publique avec des sources vérifiables avant tout plaidoyer\",\"Refuser les accords opaques qui contournent la consultation des communautés\",\"Prioriser la souveraineté malgache en matière de numérique, ressources naturelles et éducation\",\"Publier les termes des partenariats dès leur signature\"],\"extra_paragraphs\":[]},{\"type\":\"section_rich\",\"heading\":\"Ce que cela signifie concrètement\",\"heading_style\":\"warm\",\"intro\":\"\",\"bullets\":[],\"extra_paragraphs\":[\"Chaque carte de cette page renvoie vers une fiche détaillée documentée — résumé dans le hero, contexte complet en blocs ci-dessous.\",\"Positions et projets suivent la même exigence : pas d’affirmation anonyme, pas de statistique invérifiable.\",\"Quand nous manquons de données, nous le disons publiquement et invitons les experts à contribuer.\"]},{\"type\":\"note_panel\",\"section_title\":\"Document vivant\",\"heading_style\":\"warm\",\"message\":\"Ces principes sont revus par les instances de gouvernance du mouvement et mis à jour lorsque le terrain révèle de nouvelles exigences éthiques.\",\"submessage\":\"Dernière révision : juin 2026\"}]','official','declarations','Juin 2026 · Éthique & Transparence','','Officiel','En savoir plus','mailto:contact@govgenz.org',20,'published','2026-06-01 10:00:00','2026-06-01 21:35:10','2026-06-04 08:02:40',NULL),('alerte-contrats-miniers','fr','decl-mining-alert','Alerte sur les contrats miniers opaques','GoV Gen Z Madagascar exprime ses vives préoccupations face à la signature de contrats d\'exploitation minière sans consultation publique ni transparence suffisante sur les retombées pour les communautés locales. Nous exigeons la publication intégrale des termes contractuels.',NULL,'blocks','[{\"type\":\"section_rich\",\"heading\":\"Contexte\",\"heading_style\":\"warm\",\"intro\":\"Des contrats miniers signés sans consultation publique suffisante sapent la confiance des communautés et la transparence fiscale. Les populations locales apprennent souvent l’existence des concessions une fois les opérations lancées.\",\"bullets\":[],\"extra_paragraphs\":[]},{\"type\":\"section_rich\",\"heading\":\"Nos préoccupations\",\"heading_style\":\"warm\",\"intro\":\"\",\"bullets\":[\"Termes contractuels non publiés intégralement avant ratification parlementaire\",\"Divulgation insuffisante sur le partage des revenus avec les communautés affectées\",\"Études d’impact environnemental inaccessibles en langues locales\",\"Absence de piste d’audit indépendante sur les redevances\"],\"extra_paragraphs\":[]},{\"type\":\"section_rich\",\"heading\":\"Ce que nous exigeons\",\"heading_style\":\"teal\",\"intro\":\"GoV Gen Z Madagascar appelle à des mesures de transparence immédiates avant toute ratification de nouvelle concession minière.\",\"bullets\":[\"Publier en ligne les textes contractuels complets et leurs annexes\",\"Organiser des audiences publiques dans les régions concernées avec comptes rendus documentés\",\"Mettre en place un mécanisme indépendant de suivi des retombées communautaires\",\"Aligner les standards de publication sur les principes ITIE\"],\"extra_paragraphs\":[]},{\"type\":\"sources\",\"section_title\":\"Sources\",\"lines\":[\"ITIE — Standard de transparence des industries extractives\",\"Banque mondiale — Gouvernance des ressources naturelles (note pays Madagascar)\",\"GoV Gen Z Madagascar — notes terrain équipe Ressources naturelles (2026)\"]}]','alert','declarations','2026 · Ressources naturelles','','Alerte','Lire la position complète','mailto:contact@govgenz.org',30,'published','2026-01-15 10:00:00','2026-06-01 21:35:10','2026-06-04 08:02:40',NULL),('partenariat-ptf','fr','decl-partnership-ptf','Recherche de partenaires techniques & financiers (PTF)','GoV Gen Z Madagascar est activement en discussion avec des organisations internationales, agences de développement et institutions bilatérales pour soutenir nos 6 projets prioritaires. Les partenariats seront annoncés ici dès leur signature officielle.',NULL,'blocks','[{\"type\":\"section_rich\",\"heading\":\"Périmètre du partenariat\",\"heading_style\":\"teal\",\"intro\":\"Nous recherchons des partenaires techniques et financiers alignés sur nos six projets prioritaires : gouvernance, éducation, souveraineté numérique, santé, environnement et emploi des jeunes.\",\"bullets\":[\"Financement pluriannuel avec exigences de reporting public\",\"Co-conception avec des équipes malgaches pilotées par la jeunesse — pas de modèles imposés\",\"Transparence sur les frais de structure et la sous-traitance locale\"],\"extra_paragraphs\":[]},{\"type\":\"note_panel\",\"section_title\":\"Proposer un partenariat\",\"heading_style\":\"teal\",\"message\":\"Organisations internationales, agences de développement et institutions bilatérales : contactez-nous avec une note conceptuelle. Les partenariats signés seront annoncés sur cette page.\",\"submessage\":\"partnerships@govgenz.org\"}]','partnership','partnerships','À venir · Développement','','PTF','Proposer un partenariat','mailto:partnerships@govgenz.org',10,'published',NULL,'2026-06-01 21:35:10','2026-06-04 08:02:40',NULL),('alliance-osc','fr','decl-citizen-alliance','Appel aux OSC, associations et collectifs citoyens','Nous recherchons des organisations de la société civile, associations et collectifs de jeunesse partageant nos valeurs pour amplifier notre impact terrain à Madagascar. Ensemble, nous pouvons construire une coalition citoyenne structurée et crédible.',NULL,'blocks','[{\"type\":\"section_rich\",\"heading\":\"Qui nous invitons\",\"heading_style\":\"warm\",\"intro\":\"OSC, associations de jeunesse, collectifs citoyens et médias locaux partageant nos valeurs de gouvernance éthique et de plaidoyer documenté.\",\"bullets\":[\"Missions terrain conjointes et vérification des sources\",\"Formations partagées à l’analyse des politiques publiques\",\"Déclarations de coalition avec signataires identifiés\"],\"extra_paragraphs\":[]},{\"type\":\"note_panel\",\"section_title\":\"Rejoindre la coalition\",\"heading_style\":\"warm\",\"message\":\"Présentez votre organisation, votre zone d’action et une idée concrète de collaboration. Réponse sous 10 jours ouvrés.\",\"submessage\":\"partnerships@govgenz.org · Objet : Alliance citoyenne\"}]','partnership','partnerships','À venir · Société civile','','Alliance','Rejoindre la coalition','mailto:partnerships@govgenz.org',20,'published',NULL,'2026-06-01 21:35:10','2026-06-04 08:02:40',NULL),('partenariat-institutionnel','fr','decl-inst-partnership','Collaborations avec ambassades, universités & centres de recherche','GoV Gen Z Madagascar cherche à établir des ponts avec des institutions académiques, des ambassades et des centres de recherche pour ancrer nos positions dans la rigueur intellectuelle et bénéficier d\'une légitimité internationale.',NULL,'blocks','[{\"type\":\"section_rich\",\"heading\":\"Collaboration institutionnelle\",\"heading_style\":\"teal\",\"intro\":\"Universités, centres de recherche et missions diplomatiques peuvent ancrer nos positions dans la rigueur analytique et les bonnes pratiques internationales.\",\"bullets\":[\"Relecture experte des positions sectorielles avant publication\",\"Partenariats de recherche étudiante avec livrables crédités\",\"Conférences publiques et notes de politique à Antananarivo et en régions\"],\"extra_paragraphs\":[]},{\"type\":\"note_panel\",\"section_title\":\"Contact\",\"heading_style\":\"teal\",\"message\":\"Ambassades, facultés et instituts de recherche : présentez votre institution et le format de collaboration envisagé.\",\"submessage\":\"partnerships@govgenz.org · Objet : Partenariat institutionnel\"}]','partnership','partnerships','À venir · Institutions & Recherche','','Institutionnel','Nous contacter','mailto:partnerships@govgenz.org',30,'published',NULL,'2026-06-01 21:35:10','2026-06-04 08:02:40',NULL),('youth-public-decisions-advocacy','en','decl-youth-decisions','Youth at the heart of public decisions','GoV Gen Z Madagascar calls for the systematic inclusion of Malagasy youth in institutional decision-making — participatory budgets, advisory councils, legislative committees. The 55% who are young cannot remain spectators of their own future.',NULL,'blocks','[{\"type\":\"section_rich\",\"heading\":\"Why youth inclusion matters\",\"heading_style\":\"warm\",\"intro\":\"More than half of Madagascar\'s population is under 25. Yet youth remain under-represented in budget debates, legislative commissions and local planning bodies that shape their future.\",\"bullets\":[\"55% of Malagasy are young — INSTAT demographic projections\",\"Few participatory budget processes include under-30 delegates\",\"Advisory councils rarely publish minutes or citizen feedback\"],\"extra_paragraphs\":[]},{\"type\":\"section_rich\",\"heading\":\"What we ask public institutions\",\"heading_style\":\"teal\",\"intro\":\"GoV Gen Z Madagascar calls for concrete, measurable inclusion mechanisms — not symbolic youth forums.\",\"bullets\":[\"Reserve seats for youth delegates on legislative committees handling education, employment and digital policy\",\"Launch participatory budget pilots in at least 5 regions with published results\",\"Publish advisory council agendas, minutes and follow-up within 30 days\",\"Track youth inclusion indicators in annual governance reports\"],\"extra_paragraphs\":[]},{\"type\":\"note_panel\",\"section_title\":\"Join the advocacy\",\"heading_style\":\"teal\",\"message\":\"Institutions, media and citizens: contact us to co-sign this advocacy or propose a concrete inclusion mechanism in your sector.\",\"submessage\":\"contact@govgenz.org · Subject: Youth inclusion advocacy\"},{\"type\":\"sources\",\"section_title\":\"Sources & references\",\"lines\":[\"INSTAT — Madagascar demographic outlook (2024–2026 projections)\",\"UNDP — Youth, governance and civic participation in Africa (2023)\",\"GoV Gen Z Madagascar — internal sector mapping, governance programme (2026)\"]}]','pledge','declarations','May 2026 · Governance','','Advocacy','Support us','mailto:contact@govgenz.org',10,'published','2026-05-01 10:00:00','2026-06-01 21:35:10','2026-06-04 00:05:40',NULL),('principles-declaration-2026','en','decl-principles-2026','Principles declaration — GoV Gen Z Madagascar','GoV Gen Z Madagascar declares its full commitment to ethical, transparent governance oriented toward the Malagasy people. No decision without public documentation; no position without verifiable sources.',NULL,'blocks','[{\"type\":\"section_rich\",\"heading\":\"Our public commitments\",\"heading_style\":\"teal\",\"intro\":\"This principles declaration sets the ethical baseline for every position, project and partnership announced by GoV Gen Z Madagascar.\",\"bullets\":[\"Document every public decision with verifiable sources before advocacy\",\"Reject opaque deals that bypass community consultation\",\"Prioritise Malagasy sovereignty in digital, natural resources and education policy\",\"Publish partnership terms once agreements are signed\"],\"extra_paragraphs\":[]},{\"type\":\"section_rich\",\"heading\":\"What this means in practice\",\"heading_style\":\"warm\",\"intro\":\"\",\"bullets\":[],\"extra_paragraphs\":[\"Every declaration card on this page links to a documented detail page — summary in the hero, full context in blocks below.\",\"Positions and projects follow the same standard: no anonymous claims, no unverifiable statistics.\",\"When we lack data, we say so publicly and invite experts to contribute.\"]},{\"type\":\"note_panel\",\"section_title\":\"Living document\",\"heading_style\":\"warm\",\"message\":\"These principles are reviewed by the movement\'s governance bodies and updated when our field work reveals new ethical requirements.\",\"submessage\":\"Last reviewed: June 2026\"}]','official','declarations','June 2026 · Ethics & transparency','','Official','Learn more','mailto:contact@govgenz.org',20,'published','2026-06-01 10:00:00','2026-06-01 21:35:10','2026-06-04 00:05:40',NULL),('alert-opaque-mining','en','decl-mining-alert','Alert on opaque mining contracts','GoV Gen Z Madagascar expresses serious concern over mining contracts signed without adequate public consultation or transparency on benefits for local communities. We demand full publication of contractual terms.',NULL,'blocks','[{\"type\":\"section_rich\",\"heading\":\"Background\",\"heading_style\":\"warm\",\"intro\":\"Mining contracts signed without adequate public consultation undermine community trust and fiscal transparency. Local populations often learn about concessions only after operations begin.\",\"bullets\":[],\"extra_paragraphs\":[]},{\"type\":\"section_rich\",\"heading\":\"Our concerns\",\"heading_style\":\"warm\",\"intro\":\"\",\"bullets\":[\"Contract terms not published in full before parliamentary ratification\",\"Insufficient disclosure on revenue sharing with affected communities\",\"Environmental impact assessments not accessible in local languages\",\"No independent audit trail on royalty payments\"],\"extra_paragraphs\":[]},{\"type\":\"section_rich\",\"heading\":\"What we demand\",\"heading_style\":\"teal\",\"intro\":\"GoV Gen Z Madagascar calls for immediate transparency measures before any new mining concession is ratified.\",\"bullets\":[\"Publish full contract texts and annexes online\",\"Hold public hearings in affected regions with documented minutes\",\"Establish an independent community benefit monitoring mechanism\",\"Align disclosure standards with EITI principles\"],\"extra_paragraphs\":[]},{\"type\":\"sources\",\"section_title\":\"Sources\",\"lines\":[\"EITI — Standard for transparency in extractive industries\",\"World Bank — Governance of natural resources (Madagascar country brief)\",\"GoV Gen Z Madagascar — Natural resources sector team field notes (2026)\"]}]','alert','declarations','2026 · Natural resources','','Alert','Read full position','mailto:contact@govgenz.org',30,'published','2026-01-15 10:00:00','2026-06-01 21:35:10','2026-06-04 00:05:40',NULL),('partnership-donors','en','decl-partnership-ptf','Seeking technical & financial partners (donors)','GoV Gen Z Madagascar is in discussion with international organizations, development agencies and bilateral institutions to support our 6 priority projects. Partnerships will be announced here upon official signature.',NULL,'blocks','[{\"type\":\"section_rich\",\"heading\":\"Partnership scope\",\"heading_style\":\"teal\",\"intro\":\"We seek technical and financial partners aligned with our six priority projects: governance, education, digital sovereignty, health, environment and youth employment.\",\"bullets\":[\"Multi-year funding with public reporting requirements\",\"Co-design with Malagasy youth-led teams — not top-down templates\",\"Transparency on overhead and local subcontracting\"],\"extra_paragraphs\":[]},{\"type\":\"note_panel\",\"section_title\":\"Propose a partnership\",\"heading_style\":\"teal\",\"message\":\"International organizations, development agencies and bilateral institutions: reach out with a brief concept note. Signed partnerships will be announced on this page.\",\"submessage\":\"partnerships@govgenz.org\"}]','partnership','partnerships','Coming soon · Development','','Donors','Propose a partnership','mailto:partnerships@govgenz.org',10,'published',NULL,'2026-06-01 21:35:10','2026-06-04 00:05:40',NULL),('citizen-alliance-call','en','decl-citizen-alliance','Call to CSOs, associations and citizen collectives','We seek civil-society organizations, associations and youth collectives that share our values to amplify our field impact in Madagascar. Together we can build a structured, credible citizen coalition.',NULL,'blocks','[{\"type\":\"section_rich\",\"heading\":\"Who we invite\",\"heading_style\":\"warm\",\"intro\":\"CSOs, youth associations, citizen collectives and local media that share our values of ethical governance and documented advocacy.\",\"bullets\":[\"Joint field missions and source verification\",\"Shared training on public policy analysis\",\"Coalition statements with named signatories\"],\"extra_paragraphs\":[]},{\"type\":\"note_panel\",\"section_title\":\"Join the coalition\",\"heading_style\":\"warm\",\"message\":\"Tell us about your organization, geographic focus and one concrete collaboration idea. We respond within 10 business days.\",\"submessage\":\"partnerships@govgenz.org · Subject: Citizen alliance\"}]','partnership','partnerships','Coming soon · Civil society','','Alliance','Join the coalition','mailto:partnerships@govgenz.org',20,'published',NULL,'2026-06-01 21:35:10','2026-06-04 00:05:40',NULL),('institutional-partnership','en','decl-inst-partnership','Collaboration with embassies, universities & research centres','GoV Gen Z Madagascar seeks bridges with academic institutions, embassies and research centres to ground our positions in intellectual rigour and international legitimacy.',NULL,'blocks','[{\"type\":\"section_rich\",\"heading\":\"Institutional collaboration\",\"heading_style\":\"teal\",\"intro\":\"Universities, research centres and diplomatic missions can help ground our positions in rigorous analysis and international best practice.\",\"bullets\":[\"Expert review of sector positions before publication\",\"Student research partnerships with credited outputs\",\"Public lectures and policy briefings in Antananarivo and regions\"],\"extra_paragraphs\":[]},{\"type\":\"note_panel\",\"section_title\":\"Contact\",\"heading_style\":\"teal\",\"message\":\"Embassies, faculties and research institutes: introduce your institution and proposed collaboration format.\",\"submessage\":\"partnerships@govgenz.org · Subject: Institutional partnership\"}]','partnership','partnerships','Coming soon · Institutions & research','','Institutional','Contact us','mailto:partnerships@govgenz.org',30,'published',NULL,'2026-06-01 21:35:10','2026-06-04 00:05:40',NULL);
