INSERT INTO `structure_units` (`code`, `unit_role`, `title_fr`, `title_en`, `subtitle_en`, `subtitle_fr`, `description_fr`, `description_en`, `contact_email`, `media_id`, `media_alt`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES ('coordination','function','Coordination','Coordination','Executives · Sectoral · Regions · Diaspora','Exécutifs · Sectorielle · Régions · Diaspora','Direction générale, alignement entre équipes, pilotage des décisions stratégiques du mouvement.','General management, team alignment, strategic decision-making for the movement.','coordination@govgenz.org',NULL,NULL,1,10,'2026-06-03 22:41:37','2026-06-03 22:46:04'),('securite','function','Sécurité','Security','Preventive & corrective · Legal · Tech · Field','Préventive & curative · Legal · Tech · Field','Protection des membres, gestion des risques, sécurité des données et continuité des opérations.','Member protection, risk management, data security and operational continuity.','securite@govgenz.org',NULL,NULL,1,20,'2026-06-03 22:41:37','2026-06-03 22:46:04'),('communication','function','Communication','Communication','Strategy · Content · Networks · Outreach','Stratégie · Contenus · Réseaux · Vulgarisation','Relations presse, réseaux sociaux, contenus publics, image institutionnelle du mouvement.','Press relations, social media, public content, institutional image.','communication@govgenz.org',NULL,NULL,1,30,'2026-06-03 22:41:37','2026-06-03 22:46:04'),('partenariats','function','Partenariats','Partnerships','National and international','National et international','Relations avec les PTF, organisations internationales, ambassades et alliances citoyennes.','Relations with donors, international organizations, embassades and citizen alliances.','partnerships@govgenz.org',NULL,NULL,1,40,'2026-06-03 22:41:37','2026-06-03 22:46:04'),('rh','function','Ressources humaines','Human resources','Recruitment · Onboarding · Training','Recrutement · Onboarding · Formation','Recrutement des v