  'blocks',
  '[{"type":"structures_grid","layout":"dept","kicker":"Organization chart","title":"Organizational structure","lead":"A central executive core supported by 7 specialized departments — Paikady Taninjanaka programme.","banner_title":"Organizational structure — GoV Gen Z Madagascar","banner_subtitle":"7 departments · Paikady Taninjanaka program"},{"type":"sectors_grid","layout":"compact","kicker":"Field teams","title":"14 sector teams","lead":"Each key sector in Madagascar is covered by a dedicated team — build, innovate, serve the people.","banner_title":"Sector teams — GoV Gen Z Madagascar","banner_subtitle":"14 sectors · Madagascar"},{"type":"section_text","paragraphs":["Identity","The DNA of GoV Gen Z Madagascar","Our foundations — who we act for, what guides us, how we work, and where we are headed."]},{"type":"cards_grid","variant":"pillar_cards","cards":[{"eyebrow":"For whom","title":"Our purpose","bullets":["55% young Malagasy","Ages 12–35","The diaspora","Future generations"]},{"eyebrow":"What guides us","title":"Our values","bullets":["Integrity · Ethics","Rigor · Honesty","Honor · Efficiency","Drive to improve"]},{"eyebrow":"How","title":"Our method","bullets":["Collective intelligence","Transparent documentation","Participatory decisions","Real, measurable impact"]},{"eyebrow":"Why","title":"Our goal","bullets":["Dignity & serenity","National governance","Working public services","A better, sustainable future"]}]},{"type":"section_text","paragraphs":["Internal policies","Our ethical commitments","Principles that govern our action and safeguard institutional credibility."]},{"type":"legal_prose","presentation":"accordion","sections":[{"heading":"Ethics charter","body":"GoV Gen Z Madagascar commits to strict institutional ethics:","bullets":["Professionalism in all public communications","No unverified accusations or defamatory statements","Institutional, peaceful and non-violent tone at all times","Cited, verifiable sources for every public claim","Clear separation between analysis and opinion"]},{"heading":"Privacy & personal data","body":"Protecting member data is an absolute priority:","bullets":["No personal data published without explicit consent","Registration lists are internal only — only totals are public","Contacts limited to sectors and organizations, no sensitive data","GDPR compliance for all digital processing"]},{"heading":"Conflicts of interest","body":"GoV Gen Z Madagascar maintains full independence from partisan interests:","bullets":["No member may simultaneously represent a political party","Mandatory disclosure of any potential conflict of interest","Systematic recusal when a conflict is identified","Periodic internal audit of positions and decisions"]},{"heading":"Financial transparency","body":"Financial management meets the highest transparency standards:","bullets":["Regular publication of financial reports","Annual independent audit of accounts","Full traceability of donations and funding received","No undocumented or unapproved expenditure"]}]},{"type":"cta_panel","text":"Questions about our declarations or partnerships?","actions":[{"label":"contact@govgenz.org","href":"mailto:contact@govgenz.org","variant":"primary"},{"label":"partnerships@govgenz.org","href":"mailto:partnerships@govgenz.org","variant":"secondary"}]}]',
